import React, { useState, useEffect } from 'react';
import {
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  TextField,
  Menu,
  MenuItem,
  IconButton,
  List,
  ListItem,
  ListItemText,
  ListItemSecondaryAction,
  Divider,
  Typography,
  Tooltip,
  Chip
} from '@mui/material';
import {
  FilterList as FilterListIcon,
  Delete as DeleteIcon,
  MoreVert as MoreVertIcon,
  Add as AddIcon,
  Save as SaveIcon,
  Close as CloseIcon
} from '@mui/icons-material';

const STORAGE_KEY = 'custom_views';

export const useCustomViews = (viewType) => {
  const [views, setViews] = useState([]);
  const [currentView, setCurrentView] = useState(null);

  useEffect(() => {
    // Load saved views from localStorage
    const savedViews = JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}');
    setViews(savedViews[viewType] || []);

    // Set default view if none is selected
    if (!currentView && savedViews[viewType]?.length > 0) {
      const defaultView = savedViews[viewType].find(v => v.isDefault) || savedViews[viewType][0];
      setCurrentView(defaultView);
    }
  }, [viewType]);

  const saveView = (view) => {
    const savedViews = JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}');
    const viewTypeViews = savedViews[viewType] || [];

    // If view with same name exists, update it
    const existingIndex = viewTypeViews.findIndex(v => v.id === view.id);

    if (existingIndex >= 0) {
      viewTypeViews[existingIndex] = { ...viewTypeViews[existingIndex], ...view };
    } else {
      viewTypeViews.push({
        ...view,
        id: Date.now().toString(),
        createdAt: new Date().toISOString(),
        isDefault: viewTypeViews.length === 0 // First view is default
      });
    }

    savedViews[viewType] = viewTypeViews;
    localStorage.setItem(STORAGE_KEY, JSON.stringify(savedViews));
    setViews(viewTypeViews);

    if (!currentView || view.id === currentView.id) {
      setCurrentView(viewTypeViews.find(v => v.id === view.id) || view);
    }

    return view;
  };

  const deleteView = (id) => {
    const savedViews = JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}');
    const viewTypeViews = savedViews[viewType] || [];

    const updatedViews = viewTypeViews.filter(v => v.id !== id);
    savedViews[viewType] = updatedViews;

    localStorage.setItem(STORAGE_KEY, JSON.stringify(savedViews));
    setViews(updatedViews);

    if (currentView?.id === id) {
      setCurrentView(updatedViews[0] || null);
    }
  };

  const setDefaultView = (id) => {
    const savedViews = JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}');
    const viewTypeViews = savedViews[viewType] || [];

    const updatedViews = viewTypeViews.map(view => ({
      ...view,
      isDefault: view.id === id
    }));

    savedViews[viewType] = updatedViews;
    localStorage.setItem(STORAGE_KEY, JSON.stringify(savedViews));
    setViews(updatedViews);

    const newDefaultView = updatedViews.find(v => v.isDefault);
    if (newDefaultView) {
      setCurrentView(newDefaultView);
    }
  };

  return {
    views,
    currentView,
    saveView,
    deleteView,
    setDefaultView,
    setCurrentView
  };
};

const CustomViews = ({ 
  viewType, 
  filters = {},
  onViewChange,
  onSaveView,
  onDeleteView,
  onSetDefaultView,
  views = [],
  currentView = null,
  setCurrentView = () => {}
}) => {
  const [anchorEl, setAnchorEl] = useState(null);
  const [saveDialogOpen, setSaveDialogOpen] = useState(false);
  const [viewName, setViewName] = useState('');
  const [isPublic, setIsPublic] = useState(false);

  const handleMenuOpen = (event) => {
    setAnchorEl(event.currentTarget);
  };

  const handleMenuClose = () => {
    setAnchorEl(null);
  };

  const handleSaveViewClick = () => {
    setViewName(currentView?.name || '');
    setIsPublic(currentView?.isPublic || false);
    setSaveDialogOpen(true);
    handleMenuClose();
  };

  const handleSaveView = () => {
    if (!viewName.trim()) return;

    const view = {
      ...(currentView || {}),
      name: viewName,
      filters,
      isPublic,
      updatedAt: new Date().toISOString()
    };

    const savedView = onSaveView ? onSaveView(view) : view;
    setCurrentView(savedView);
    setSaveDialogOpen(false);
  };

  const handleDeleteView = (view) => {
    if (onDeleteView) {
      onDeleteView(view);
    }
    handleMenuClose();
  };

  const handleSetDefaultView = (view) => {
    if (onSetDefaultView) {
      onSetDefaultView(view);
    }
    handleMenuClose();
  };

  const handleViewSelect = (view) => {
    setCurrentView(view);
    if (onViewChange) {
      onViewChange(view);
    }
    handleMenuClose();
  };

  return (
    <>
      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
        <Typography variant="subtitle2" color="textSecondary">
          View:
        </Typography>

        <Button
          variant="outlined"
          size="small"
          onClick={handleMenuOpen}
          startIcon={<FilterListIcon />}
          endIcon={<MoreVertIcon />}
          sx={{ textTransform: 'none' }}
        >
          {currentView?.name || 'Default View'}
        </Button>

        {currentView?.isDefault && (
          <Chip 
            label="Default" 
            size="small" 
            color="primary"
            variant="outlined"
          />
        )}
      </Box>

      <Menu
        anchorEl={anchorEl}
        open={Boolean(anchorEl)}
        onClose={handleMenuClose}
        anchorOrigin={{
          vertical: 'bottom',
          horizontal: 'left',
        }}
        transformOrigin={{
          vertical: 'top',
          horizontal: 'left',
        }}
      >
        <Box sx={{ width: 300, maxHeight: 400, overflow: 'auto' }}>
          <Box sx={{ p: 2 }}>
            <Typography variant="subtitle2" color="textSecondary">
              SAVED VIEWS
            </Typography>
          </Box>

          <List dense>
            {views.length === 0 ? (
              <ListItem>
                <Typography variant="body2" color="textSecondary">
                  No saved views
                </Typography>
              </ListItem>
            ) : (
              views.map((view) => (
                <React.Fragment key={view.id}>
                  <ListItem 
                    button 
                    selected={currentView?.id === view.id}
                    onClick={() => handleViewSelect(view)}
                  >
                    <ListItemText 
                      primary={view.name} 
                      secondary={`${Object.keys(view.filters || {}).length} filters`}
                    />
                    {view.isDefault && (
                      <Chip 
                        label="Default" 
                        size="small" 
                        color="primary"
                        variant="outlined"
                        sx={{ ml: 1 }}
                      />
                    )}
                    <ListItemSecondaryAction>
                      <IconButton 
                        size="small"
                        onClick={(e) => {
                          e.stopPropagation();
                          setCurrentView(view);
                          handleMenuClose();
                        }}
                      >
                        <MoreVertIcon fontSize="small" />
                      </IconButton>
                    </ListItemSecondaryAction>
                  </ListItem>
                  <Divider variant="inset" component="li" />
                </React.Fragment>
              ))
            )}
          </List>

          <Divider />

          <Box sx={{ p: 1 }}>
            <Button 
              fullWidth 
              startIcon={<AddIcon />}
              onClick={handleSaveViewClick}
              disabled={Object.keys(filters).length === 0}
            >
              Save current view
            </Button>
          </Box>
        </Box>
      </Menu>

      {/* Save View Dialog */}
      <Dialog open={saveDialogOpen} onClose={() => setSaveDialogOpen(false)} maxWidth="sm" fullWidth>
        <DialogTitle>
          {currentView?.id ? 'Update View' : 'Save View'}
        </DialogTitle>
        <DialogContent>
          <TextField
            autoFocus
            margin="dense"
            label="View name"
            fullWidth
            variant="outlined"
            value={viewName}
            onChange={(e) => setViewName(e.target.value)}
            sx={{ mb: 2 }}
          />

          <FormControlLabel
            control={
              <Checkbox
                checked={isPublic}
                onChange={(e) => setIsPublic(e.target.checked)}
                color="primary"
              />
            }
            label="Make this view public"
          />

          {Object.keys(filters).length > 0 && (
            <Box sx={{ mt: 2 }}>
              <Typography variant="subtitle2" gutterBottom>
                Current filters:
              </Typography>
              <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1 }}>
                {Object.entries(filters).map(([key, value]) => (
                  <Chip 
                    key={key}
                    label={`${key}: ${value}`}
                    size="small"
                    variant="outlined"
                  />
                ))}
              </Box>
            </Box>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setSaveDialogOpen(false)}>
            Cancel
          </Button>
          <Button 
            onClick={handleSaveView} 
            variant="contained" 
            color="primary"
            disabled={!viewName.trim()}
            startIcon={<SaveIcon />}
          >
            {currentView?.id ? 'Update' : 'Save'}
          </Button>
        </DialogActions>
      </Dialog>

      {/* View Actions Menu */}
      <Menu
        anchorEl={anchorEl}
        open={Boolean(anchorEl) && Boolean(currentView)}
        onClose={handleMenuClose}
      >
        {currentView && !currentView.isDefault && (
          <MenuItem onClick={() => handleSetDefaultView(currentView)}>
            Set as default
          </MenuItem>
        )}
        <MenuItem onClick={handleSaveViewClick}>
          Save changes
        </MenuItem>
        {currentView && (
          <MenuItem onClick={() => handleDeleteView(currentView)}>
            <Box color="error.main" display="flex" alignItems="center">
              <DeleteIcon fontSize="small" sx={{ mr: 1 }} />
              Delete view
            </Box>
          </MenuItem>
        )}
      </Menu>
    </>
  );
};

export default CustomViews;
